import{_ as t,c as s,a0 as a,o as i}from"./chunks/framework.BGabeMLJ.js";const k=JSON.parse('{"title":"FLAME Hub with Docker Compose","description":"","frontmatter":{},"headers":[],"relativePath":"guide/deployment/hub-docker-compose.md","filePath":"guide/deployment/hub-docker-compose.md"}'),o={name:"guide/deployment/hub-docker-compose.md"};function n(h,e,r,d,l,p){return i(),s("div",null,e[0]||(e[0]=[a(`<h1 id="flame-hub-with-docker-compose" tabindex="-1">FLAME Hub with Docker Compose <a class="header-anchor" href="#flame-hub-with-docker-compose" aria-label="Permalink to &quot;FLAME Hub with Docker Compose&quot;">​</a></h1><p>The Docker Compose setup is intended for development and evaluation. It uses fixed development credentials, mounts the Docker socket for the core worker, and does not include Harbor. Use the <a href="./hub-installation.html">Helm deployment</a> for a production Hub.</p><h2 id="get-the-configuration" tabindex="-1">Get the configuration <a class="header-anchor" href="#get-the-configuration" aria-label="Permalink to &quot;Get the configuration&quot;">​</a></h2><p>Clone the repository and enter the Compose directory:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/PrivateAIM/hub-deployment.git</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hub-deployment/docker-compose</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span></span></code></pre></div><p>The executable configuration remains in the Hub Deployment repository:</p><ul><li><a href="https://github.com/PrivateAIM/hub-deployment/blob/master/docker-compose/docker-compose.yml" target="_blank" rel="noreferrer"><code>docker-compose.yml</code></a></li><li><a href="https://github.com/PrivateAIM/hub-deployment/blob/master/docker-compose/nginx.conf" target="_blank" rel="noreferrer"><code>nginx.conf</code></a></li><li><a href="https://github.com/PrivateAIM/hub-deployment/blob/master/docker-compose/.env.example" target="_blank" rel="noreferrer"><code>.env.example</code></a></li></ul><h2 id="configure-the-environment" tabindex="-1">Configure the environment <a class="header-anchor" href="#configure-the-environment" aria-label="Permalink to &quot;Configure the environment&quot;">​</a></h2><p>The example <code>.env</code> supports these basic overrides:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Purpose</th></tr></thead><tbody><tr><td><code>HUB_IMAGE</code></td><td><code>ghcr.io/privateaim/hub</code></td><td>Hub container image repository</td></tr><tr><td><code>HUB_IMAGE_TAG</code></td><td><code>latest</code></td><td>Hub image tag</td></tr><tr><td><code>SUBNET</code></td><td><code>172.40.1.0/24</code></td><td>Compose network subnet</td></tr></tbody></table><p>The Compose file also accepts service URL overrides such as <code>PUBLIC_URL</code>, <code>AUTHUP_PUBLIC_URL</code>, <code>CORE_PUBLIC_URL</code>, and <code>STORAGE_PUBLIC_URL</code>. Review the current Compose file before changing them.</p><p>Analyses require a reachable Harbor registry. This setup does not deploy one, so either <a href="https://goharbor.io/docs/latest/install-config/" target="_blank" rel="noreferrer">install Harbor separately</a> or use an existing instance. Harbor must be reachable over HTTPS. Set <code>HARBOR_URL</code> without the scheme and include the credentials:</p><div class="language-dotenv vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">dotenv</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">HARBOR_URL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;username&gt;:&lt;password&gt;@&lt;harbor-host&gt;</span></span></code></pre></div><p>Do not commit the populated <code>.env</code> file.</p><h2 id="start-and-inspect-the-stack" tabindex="-1">Start and inspect the stack <a class="header-anchor" href="#start-and-inspect-the-stack" aria-label="Permalink to &quot;Start and inspect the stack&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ps</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span></span></code></pre></div><p>The bundled NGINX listens on <code>http://localhost:3000</code> and routes the Hub services by path. Stop the stack with:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> down</span></span></code></pre></div><p>Named volumes retain database and object-store data. Use <code>docker compose down --volumes</code> only when you intentionally want to delete that local data.</p>`,19)]))}const u=t(o,[["render",n]]);export{k as __pageData,u as default};
